const s=load("pub"); const py=String.raw`import hashlib,json,re,subprocess,sys
from pathlib import Path
from urllib.parse import unquote
stage=Path(sys.argv[1])
root=Path.cwd()
tree=stage/'worktree'
def git(*args,cwd=tree):
    return subprocess.check_output(['git',*args],cwd=cwd)
def digest(b):
    return hashlib.sha256(b).hexdigest().upper()
def lines(p):
    return p.read_text(encoding='utf-8-sig').splitlines()
def normalize(b):
    return b.replace(b'\r\n',b'\n')
scope=set(lines(stage/'scope.txt'))
manifest=json.loads((stage/'before-after.json').read_text())
approved={r['path']:r for r in manifest}
created={p for p,r in approved.items() if r['before'] is None}
paths=set(git('diff','--cached','--name-only').decode().splitlines())
assert paths==scope|created and len(paths)==23 and all(p.endswith('.md') for p in paths)
assert 'AGENTS.md' not in paths
status=set(lines(stage/'local-status-before.txt'))
assert status==set(git('status','--porcelain=v1','-uall',cwd=root).decode().splitlines())
assert len(status)==89 and all(digest((root/r[3:]).read_bytes())==approved[r[3:]]['after'] for r in status)
assert lines(stage/'local-index-before.txt')==git('ls-files','--stage',cwd=root).decode().splitlines()
def slug(h):
    return re.sub(r'[^\w -]','',h.lower().strip()).replace(' ','-')
def invalid(path,body,lookup):
    misses=set()
    for ref in re.findall(r'\[[^\]\n]*\]\(([^)\n]+)\)',body):
        if '://' in ref or ref.startswith('mailto:'):
            continue
        file,_,anchor=unquote(ref).partition('#')
        target=tree/path.parent/file if file else tree/path
        found=lookup(target)
        if found is None or (anchor and target.suffix=='.md' and anchor not in {slug(h) for h in re.findall(r'^#{1,6} (.+)$',found,re.M)}):
            misses.add(ref)
    return misses
basepaths=set(git('ls-tree','-r','--name-only','HEAD').decode().splitlines())
def original(target):
    p=target.resolve().relative_to(tree).as_posix()
    if p in basepaths:
        return git('show','HEAD:'+p).decode(errors='replace') if p.endswith('.md') else ''
    return '' if any(x.startswith(p+'/') for x in basepaths) else None
def current(p):
    return p.read_text(encoding='utf-8-sig') if p.is_file() and p.suffix=='.md' else '' if p.exists() else None
proof=[]
inherited={}
for p in sorted(paths):
    index=git('show',':'+p)
    before=git('show','HEAD:'+p) if p in basepaths else None
    assert normalize((tree/p).read_bytes())==index
    active=(root/p).read_bytes()
    assert digest(active)==approved[p]['after']
    if p=='HANDOFF.md':
        a=normalize(active).decode()
        section=a[a.index('\n## Documentation closure'):a.index('\n## NSE historical source depth')]
        baseline=before.decode()
        assert index.decode()==baseline.replace('\n', '\n'+section,1)
    else:
        assert normalize(active)==index
        if before is not None and digest(before)!=approved[p]['before']:
            # The closure manifest hashes checkout bytes, which may use CRLF.
            assert digest(before.replace(b'\n',b'\r\n'))==approved[p]['before'],p
    body=index.decode()
    assert body.startswith('# ') and body.endswith('\n') and len(re.findall(r'^# ',body,re.M))==1
    assert len(re.findall(r'^ *\x60{3}',body,re.M))%2==0
    bad=invalid(Path(p),body,current)
    assert bad<=invalid(Path(p),(before or b'').decode(),original),(p,bad)
    if bad:
        inherited[p]=sorted(bad)
    proof.append(dict(path=p,before_sha256=digest(before) if before else None,
        after_sha256=digest(index),blob=git('rev-parse',':'+p).decode().strip()))
(stage/'publication-manifest.json').write_text(json.dumps(proof,indent=2))
(stage/'inherited-links.json').write_text(json.dumps(inherited,indent=2))
print('PASS 23 exact staged Markdown paths and publication hashes, including isolated HANDOFF projection')
print('PASS all 89 active paths match closure hashes, and active index/status are unchanged')
print('PASS Markdown and no newly broken links. Inherited unresolved links:',sum(map(len,inherited.values())))
